<?php
namespace App\Http\Controllers;use App\Models\HeatmapRun;use App\Models\Survey;use App\Services\IdwHeatmapService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class HeatmapController extends Controller{
 public function index(Request $r,Survey $survey):View{abort_unless($r->user()->can('dashboard.view'),403);$survey->load(['floor.building','floorPlan','points.measurements']);$runs=$survey->heatmaps()->latest()->get();return view('heatmaps.index',compact('survey','runs'));}
 public function store(Request $r,Survey $survey,IdwHeatmapService $service):JsonResponse{abort_unless($r->user()->can('heatmaps.generate'),403);$d=$r->validate(['grid_width'=>'nullable|integer|between:20,200','grid_height'=>'nullable|integer|between:20,200','power'=>'nullable|numeric|between:1,5','weak_threshold'=>'nullable|numeric|between:-120,0','max_distance'=>'nullable|numeric|between:0.02,1']);$run=$survey->heatmaps()->create(['floor_plan_id'=>$survey->floor_plan_id,'generated_by'=>$r->user()->id,'metric'=>'rssi','algorithm'=>'idw','algorithm_version'=>'1.1','status'=>'processing','grid_width'=>$d['grid_width']??80,'grid_height'=>$d['grid_height']??60,'power'=>$d['power']??2,'weak_threshold'=>$d['weak_threshold']??-75,'parameters'=>$d]);try{$result=$service->generate($survey,$d);$run->update(['status'=>'completed','source_point_count'=>$result['source_point_count'],'coverage_percent'=>$result['coverage_percent'],'estimated_area_percent'=>$result['estimated_area_percent'],'source_measurement_ids'=>$result['source_measurement_ids'],'grid_data'=>$result['grid'],'confidence_grid'=>$result['confidence'],'parameters'=>$result['parameters'],'generated_at'=>now()]);return response()->json($run->refresh(),201);}catch(\Throwable $e){$run->update(['status'=>'failed','error_message'=>$e->getMessage()]);throw $e;}}
 public function show(Request $r,HeatmapRun $heatmapRun):JsonResponse{abort_unless($r->user()->can('dashboard.view'),403);return response()->json($heatmapRun);}
}
